// Skip non-text messages or those without a Message-ID (rare, but possible).
// Decide whether to-process or to-skip based on whitelist envs.

const item = $input.first();
const json = item.json || {};
const headers = json.headers || {};
const messageId = headers['message-id'] || headers['Message-ID'] || json.messageId;
const from = (json.from && (json.from.text || (Array.isArray(json.from.value) && json.from.value[0] && json.from.value[0].address))) || '';
const subject = String(json.subject || '');

if (!messageId) {
  return [{ json: { skipped: true, reason: 'no-message-id', subject, from } }];
}

const whitelistRaw = $env.EMAIL_FROM_WHITELIST || '';
const whitelist = whitelistRaw.split(',').map(s => s.trim().toLowerCase()).filter(Boolean);
if (whitelist.length > 0) {
  const fromLower = String(from).toLowerCase();
  const matched = whitelist.some(domain => fromLower.includes('@' + domain) || fromLower.endsWith('@' + domain) || fromLower.includes('<' + domain) || fromLower === domain);
  if (!matched) {
    return [{ json: { skipped: true, reason: 'from-domain-not-whitelisted', from, subject } }];
  }
}

const includeRaw = $env.EMAIL_SUBJECT_INCLUDE || '';
const include = includeRaw.split(',').map(s => s.trim().toLowerCase()).filter(Boolean);
if (include.length > 0) {
  const subjLower = subject.toLowerCase();
  const matched = include.some(kw => subjLower.includes(kw));
  if (!matched) {
    return [{ json: { skipped: true, reason: 'subject-keyword-not-matched', subject, from } }];
  }
}

return [{
  json: {
    skipped: false,
    messageId,
    from,
    subject,
    raw: json,
  },
}];

// Per-key sliding-window rate limit on the Notion API call, opt-in.
// Default 60 ops / 5 min, scoped to the workflow as a whole.

if ($env.RATE_LIMIT_ENABLED !== '1') {
  return $input.all();
}

const LIMIT = 60;
const WINDOW_MS = 5 * 60 * 1000;
const MAX_KEYS = 5000;

const data = $getWorkflowStaticData('global');
data.rateBuckets = data.rateBuckets || {};
const buckets = data.rateBuckets;
const now = Date.now();

for (const k of Object.keys(buckets)) {
  buckets[k] = (buckets[k] || []).filter(t => now - t < WINDOW_MS);
  if (buckets[k].length === 0) delete buckets[k];
}
if (Object.keys(buckets).length > MAX_KEYS) {
  const oldest = Object.entries(buckets).sort((a, b) => (a[1][0] || 0) - (b[1][0] || 0)).slice(0, 100);
  for (const [k] of oldest) delete buckets[k];
}

const key = 'notion-write';
const hits = buckets[key] || [];
if (hits.length >= LIMIT) {
  throw new Error('RATE_LIMIT_EXCEEDED: ' + LIMIT + ' Notion writes per ' + Math.round(WINDOW_MS / 60000) + ' minutes reached');
}
buckets[key] = [...hits, now];

return $input.all();

// 5-minute idempotency window on Message-ID hash, opt-in.
// Skips items where Filter already marked skipped=true.

const crypto = require('crypto');

if ($env.IDEMPOTENCY_ENABLED !== '1') {
  return $input.all();
}

const WINDOW_MS = 5 * 60 * 1000;
const MAX_KEYS = 5000;

const data = $getWorkflowStaticData('global');
data.seenKeys = data.seenKeys || {};
const seen = data.seenKeys;
const now = Date.now();

for (const k of Object.keys(seen)) {
  if (now - seen[k] > WINDOW_MS) delete seen[k];
}
if (Object.keys(seen).length > MAX_KEYS) {
  const oldest = Object.entries(seen).sort((a, b) => a[1] - b[1]).slice(0, 500);
  for (const [k] of oldest) delete seen[k];
}

const out = [];
for (const item of $input.all()) {
  const j = item.json || {};
  if (j.skipped) { out.push(item); continue; }
  const messageId = j.messageId || '';
  const dedupKey = crypto.createHash('sha256').update(String(messageId), 'utf8').digest('hex').slice(0, 32);
  if (seen[dedupKey]) {
    out.push({ json: { ...j, skipped: true, reason: 'duplicate-message-id', dedupKey } });
    continue;
  }
  seen[dedupKey] = now;
  out.push(item);
}
return out;

// Redis variant for clustered n8n:
// const result = await redis.set('email-idem:' + dedupKey, '1', 'EX', 300, 'NX');
// if (result === null) treat-as-duplicate;

// Normalize the email payload into a stable Notion page-create shape.
// Strip HTML to plain text for the snippet. Cap snippet length.

const stripHtml = (s) => String(s || '')
  .replace(/<style[\s\S]*?<\/style>/gi, '')
  .replace(/<script[\s\S]*?<\/script>/gi, '')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/gi, ' ')
  .replace(/&amp;/gi, '&')
  .replace(/&lt;/gi, '<')
  .replace(/&gt;/gi, '>')
  .replace(/&quot;/gi, '"')
  .replace(/&#x27;/gi, "'")
  .replace(/&#39;/gi, "'")
  .replace(/\s+/g, ' ')
  .trim();

const SNIPPET_LIMIT = 1800; // Notion rich_text segment soft-limit ~2000 chars
const SUBJECT_LIMIT = 200;

const out = [];
for (const item of $input.all()) {
  const j = item.json || {};
  if (j.skipped) {
    out.push({ json: { ...j, normalizedSkipped: true } });
    continue;
  }
  const raw = j.raw || {};
  const subject = String(j.subject || '(no subject)').slice(0, SUBJECT_LIMIT);
  const from = String(j.from || '').slice(0, 200);
  const bodyText = raw.text || stripHtml(raw.html || '');
  const snippet = String(bodyText).slice(0, SNIPPET_LIMIT);
  const receivedAt = (raw.date && new Date(raw.date).toISOString()) || new Date().toISOString();
  const attachments = Array.isArray(raw.attachments) ? raw.attachments : [];

  out.push({ json: {
    skipped: false,
    messageId: j.messageId,
    subject,
    from,
    snippet,
    receivedAt,
    attachmentCount: attachments.length,
  }});
}
return out;

// Pass-through filter: drops items already marked skipped, only forwards real ones.

const out = [];
for (const item of $input.all()) {
  const j = item.json || {};
  if (!j.skipped) out.push(item);
}
if (out.length === 0) {
  return [{ json: { skipped: true, reason: 'all-items-filtered-or-deduped' } }];
}
return out;

// Fallback when the Notion call fails. Build a structured error log
// and post a Slack alert if SLACK_OPS_WEBHOOK is set.

const input = $input.first();
const raw = input.json || {};
const errorRaw = raw.error || raw;
const isHttpError = !!(errorRaw && (errorRaw.message || errorRaw.code));
const errorMessage = isHttpError ? (errorRaw.message || 'Notion API error') : 'Unknown error: ' + JSON.stringify(errorRaw).slice(0, 200);

// Pull the email metadata for the alert. Fall back gracefully if missing.
const forward = $('Forward Live Items Only').first();
const emailMeta = (forward && forward.json) || {};

return [{
  json: {
    notionError: { message: errorMessage, raw: errorRaw },
    email: { subject: emailMeta.subject, from: emailMeta.from, messageId: emailMeta.messageId },
  },
}];
